mapper.update:
UPDATE knowledge_outline_node
SET parent_id = CASE id

    WHEN #{node.id} THEN #{node.parentId}

END
WHERE id IN

    #{node.id}

mapper.select:
SELECT n.id
FROM knowledge_outline_node n
JOIN knowledge_file f ON n.file_id = f.id
JOIN knowledge k ON f.knowledge_id = k.id
WHERE k.user_id = #{userId}
  AND (

    n.title LIKE CONCAT('%', #{kw}, '%') OR n.heading_path LIKE CONCAT('%', #{kw}, '%')

  )
ORDER BY n.id
LIMIT #{limit}
